<?php
namespace Tests\Feature;use App\Models\Video;use App\Models\VideoCategory;use App\Models\VideoPlaylist;use App\Models\VideoSeries;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class VideoLibraryTest extends TestCase{use RefreshDatabase;
 public function test_library_only_exposes_published_videos_with_series_playlist_and_subtitle():void{$category=VideoCategory::create(['name'=>'Cidade','slug'=>'cidade']);$series=VideoSeries::create(['video_category_id'=>$category->id,'title'=>'Jornal','slug'=>'jornal','is_published'=>true]);$published=Video::create(['video_category_id'=>$category->id,'video_series_id'=>$series->id,'title'=>'Edição publicada','slug'=>'edicao-publicada','provider'=>'file','video_path'=>'videos/a.mp4','subtitle_path'=>'videos/a.vtt','is_published'=>true,'published_at'=>now()]);Video::create(['title'=>'Rascunho secreto','slug'=>'rascunho','provider'=>'file','video_path'=>'videos/b.mp4','is_published'=>false]);$playlist=VideoPlaylist::create(['title'=>'Destaques','slug'=>'destaques','is_published'=>true]);$playlist->videos()->attach($published->id,['position'=>0]);$this->get('/videos')->assertOk()->assertSee('Edição publicada')->assertSee('Destaques')->assertDontSee('Rascunho secreto');$this->get('/videos/edicao-publicada')->assertOk()->assertSee('videos/a.vtt');$this->get('/videos/rascunho')->assertNotFound();}
}
